def comprimir_repeticiones(texto: str) -> str:
    if not texto:
        return ""

    result = []
    current_char = texto[0]
    count = 1

    for char in texto[1:]:
        if char == current_char:
            count += 1
        else:
            result.append(f"{current_char}{count}")
            current_char = char
            count = 1

    result.append(f"{current_char}{count}")
    return "".join(result)

def aplanar(datos: list) -> list:
    result = []
    for item in datos:
        if isinstance(item, (list, tuple)):
            result.extend(aplanar(item))
        else:
            result.append(item)
    return result

import re
from datetime import date

def parsear_fecha(texto: str) -> str:
    # Normalize the string by stripping leading/trailing spaces
    texto = texto.strip()

    # Define the month names in Spanish
    meses_espanoles = {
        'enero': 1, 'febrero': 2, 'marzo': 3, 'abril': 4, 'mayo': 5, 'junio': 6,
        'julio': 7, 'agosto': 8, 'septiembre': 9, 'octubre': 10, 'noviembre': 11, 'diciembre': 12
    }

    # Helper function to check if a year is a leap year
    def es_bisiesto(year):
        return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

    # Helper function to check if a date is valid
    def es_fecha_valida(day, mes, año):
        try:
            # Try to create a date object
            date(year=año, month=mes, day=day)
            return True
        except ValueError:
            return False

    # Format 1: AAAA-MM-DD
    if re.match(r'^\d{4}-\d{2}-\d{2}$', texto):
        año, mes, día = texto.split('-')
        if len(año) != 4 or len(mes) != 2 or len(día) != 2:
            raise ValueError("Formato no válido")
        if not es_fecha_valida(int(día), int(mes), int(año)):
            raise ValueError("Fecha no existe")
        return f"{año}-{mes}-{día}"

    # Format 2: DD/MM/AAAA
    if re.match(r'^\d{2}/\d{2}/\d{4}$', texto):
        día, mes, año = texto.split('/')
        if not (len(día) == 2 and len(mes) == 2 and len(año) == 4):
            raise ValueError("Formato no válido")
        if not es_fecha_valida(int(día), int(mes), int(año)):
            raise ValueError("Fecha no existe")
        return f"{año}-{mes}-{día}"

    # Format 3: D de MES de AAAA
    # Split by " de " (case-insensitive for the word "de")
    # We'll split by the literal string " de " and handle variations
    partes = re.split(r'\s*de\s*', texto, flags=re.IGNORECASE)
    if len(partes) != 3:
        raise ValueError("Formato no válido")

    # The parts are: [día, MES, AAAA]
    día_str, mes_str, año_str = partes

    # Validate día
    try:
        día = int(día_str)
    except ValueError:
        raise ValueError("Día no es un número válido")

    # Validate año
    if len(año_str) != 4:
        raise ValueError("Año debe tener 4 dígitos")

    # Validate mes (en español)
    mes_nulo = True
    for clave, cod in meses_espanoles.items():
        if mes_str.lower() == clave:
            mes = cod
            mes_nulo = False
            break
    if mes_nulo:
        raise ValueError("Mes no es válido en español")

    # Validate fecha
    if not es_fecha_valida(día, mes, int(año_str)):
        raise ValueError("Fecha no existe")

    return f"{año_str}-{mes}-{día}"

def promedio_movil(valores: list[float], ventana: int) -> list[float]:
    if ventana <= 0 or ventana > len(valores):
        return []
    resultado = []
    for i in range(len(valores) - ventana + 1):
        resultado.append(sum(valores[i:i + ventana]) / ventana)
    return resultado

from typing import List

def mochila(pesos: List[int], valores: List[int], capacidad: int) -> tuple[int, List[int]]:
    n = len(pesos)
    if n != len(valores):
        raise ValueError("pesos y valores deben tener la misma longitud")
    if n == 0:
        return (0, [])
    for w in pesos:
        if w < 0:
            raise ValueError("peso no puede ser negativo")
    if capacidad < 0:
        raise ValueError("capacidad no puede ser negativa")

    # Inicializar mejoras
    best_value = -1
    best_weight = 0
    best_count = 0
    best_indices = []

    # Iterar sobre todas las combinaciones
    for mask in range(1 << n):
        total_weight = 0
        total_value = 0
        count = 0
        indices = []
        for i in range(n):
            if mask & (1 << i):
                total_weight += pesos[i]
                total_value += valores[i]
                count += 1
                indices.append(i)
        if total_weight > capacidad:
            continue
        # Comparar con mejoresas
        if total_value > best_value:
            best_value = total_value
            best_weight = total_weight
            best_count = count
            best_indices = indices
        elif total_value == best_value:
            if total_weight < best_weight:
                best_value = total_value
                best_weight = total_weight
                best_count = count
                best_indices = indices
            elif total_weight == best_weight:
                if count < best_count:
                    best_value = total_value
                    best_weight = total_weight
                    best_count = count
                    best_indices = indices
                elif count == best_count:
                    # Comparar índices lexicográficamente
                    if indices < best_indices:
                        best_value = total_value
                        best_weight = total_weight
                        best_count = count
                        best_indices = indices

    return (best_value, best_indices)

from collections import OrderedDict


class CacheLRU:
    def __init__(self, capacidad: int):
        if capacidad < 0:
            raise ValueError("Capacidad no puede ser negativa")
        self.capacidad = capacidad
        self._datos = OrderedDict()

    def get(self, clave):
        if clave not in self._datos:
            return None
        # Move to end to mark as recently used
        self._datos.move_to_end(clave)
        return self._datos[clave]

    def put(self, clave, valor):
        if clave in self._datos:
            # Update value and mark as recently used
            self._datos.move_to_end(clave)
            self._datos[clave] = valor
        else:
            # Key is new: check if cache is full and needs eviction
            if len(self._datos) >= self.capacidad:
                # Remove least recently used item
                self._datos.popitem(last=False)
            self._datos[clave] = valor

    def __len__(self):
        return len(self._datos)
